 void stopRecognizer(){systemActive=false;systemGeneration++;CallBailianAsr b=bailianAsr;bailianAsr=null;if(b!=null)b.cancel();CallHttpAsr h=httpAsr;httpAsr=null;if(h!=null)h.cancel();SpeechRecognizer r=recognizer;recognizer=null;if(r!=null){r.cancel();r.destroy();}}
