 void route(){if(Build.VERSION.SDK_INT>=31){AudioDeviceInfo selected=null;for(AudioDeviceInfo d:audio.getAvailableCommunicationDevices()){if(speaker&&d.getType()==AudioDeviceInfo.TYPE_BUILTIN_SPEAKER){selected=d;break;}if(!speaker&&(d.getType()==AudioDeviceInfo.TYPE_BLUETOOTH_SCO||d.getType()==AudioDeviceInfo.TYPE_BLE_HEADSET||d.getType()==AudioDeviceInfo.TYPE_WIRED_HEADSET)){if(d.getType()!=AudioDeviceInfo.TYPE_BLUETOOTH_SCO&&d.getType()!=AudioDeviceInfo.TYPE_BLE_HEADSET||checkSelfPermission("android.permission.BLUETOOTH_CONNECT")==PackageManager.PERMISSION_GRANTED){selected=d;break;}}if(!speaker&&d.getType()==AudioDeviceInfo.TYPE_BUILTIN_EARPIECE)selected=d;}if(selected!=null&&!audio.setCommunicationDevice(selected))throw new IllegalStateException("系统拒绝了音频设备切换");}else audio.setSpeakerphoneOn(speaker);}
